// Some portions generated by Codex
package org.eclipse.rdf4j.query.parser.gql;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.concurrent.Callable;
import java.util.concurrent.Executors;

import org.eclipse.rdf4j.query.MalformedQueryException;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.parser.ParsedQuery;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.Test;

class GqlParserSyntaxTest {

	private final GQLParser parser = new GQLParser();

	@Test
	void registersGqlAndPreservesProjectionOrder() {
		assertEquals(QueryLanguage.GQL, QueryLanguage.valueOf("gql"));
		ParsedQuery parsed = QueryParserUtil.parseQuery(QueryLanguage.GQL,
				"RETURN 1 AS first, 2 AS second, 3 AS third", null);
		assertEquals(List.of("first", "second", "third"), new ArrayList<>(parsed.getTupleExpr().getBindingNames()));
	}

	@Test
	void quotedKeywordsRemainIdentifiers() {
		ParsedQuery parsed = parser.parseQuery("MATCH (node:\"urn:Person\") RETURN node AS \"RETURN\"", null);
		assertEquals(Set.of("RETURN"), parsed.getTupleExpr().getBindingNames());
	}

	@Test
	void ignoresCommentSyntaxInsideStrings() {
		ParsedQuery parsed = parser.parseQuery("/* a */ RETURN '--not a comment /* either */' AS result; // end", null);
		assertEquals(Set.of("result"), parsed.getTupleExpr().getBindingNames());
	}

	@Test
	void rejectsMalformedOrUnsupportedQueriesWithoutIgnoringTrailingText() {
		for (String query : List.of("", "MATCH (a) RETURN", "RETURN 1 AS value; DROP GRAPH x",
				"RETURN COUNT(SUM(1)) AS value", "MATCH (n) RETURN missing", "RETURN 1 AS value LIMIT -1",
				"RETURN 1 AS value OFFSET 1.5", "MATCH (a)-[:`urn:p`]->{2,1}(b) RETURN b",
				"MATCH (a)-[:`urn:p`]->{0,33}(b) RETURN b", "RETURN 1 AS value UNION RETURN 2 AS other",
				"RETURN COUNT(DISTINCT *) AS value", "RETURN 1 = 2 = 3 AS value")) {
			MalformedQueryException exception = assertThrows(MalformedQueryException.class,
					() -> parser.parseQuery(query, null), query);
			assertTrue(exception.getMessage().contains("line"), exception.getMessage());
		}
	}

	@Test
	void rejectsQuotedComparisonOperators() {
		for (String operator : List.of("=", "<>", "!=", "<", "<=", ">", ">=")) {
			for (String quote : List.of("'", "\"", "`")) {
				String query = "RETURN 1 " + quote + operator + quote + " 1 AS value";
				assertThrows(MalformedQueryException.class, () -> parser.parseQuery(query, null), query);
			}
		}
	}

	@Test
	void rejectsNonBooleanLiteralOperands() {
		for (String query : List.of("RETURN 1 AND TRUE AS value", "RETURN 'yes' OR FALSE AS value",
				"RETURN NOT 0 AS value", "RETURN TRUE XOR 1 AS value")) {
			assertThrows(MalformedQueryException.class, () -> parser.parseQuery(query, null), query);
		}
	}

	@Test
	void boundsNestedExpressionsBeforeBuildingAnUnsafeTree() {
		String expression = "(".repeat(129) + "1" + ")".repeat(129);
		assertThrows(MalformedQueryException.class,
				() -> parser.parseQuery("RETURN " + expression + " AS value", null));
	}

	@Test
	void boundsLongFlatExpressions() {
		String expression = "1 + ".repeat(300) + "1";
		assertThrows(MalformedQueryException.class,
				() -> parser.parseQuery("RETURN " + expression + " AS value", null));
	}

	@Test
	void boundsCopiedExpressionsAndKeepsNullPredicatesLinear() {
		String between = "1";
		String nullPredicate = "NULL";
		for (int i = 0; i < 24; i++) {
			between = "(" + between + " BETWEEN 0 AND 1)";
			nullPredicate = "(" + nullPredicate + " IS NULL)";
		}
		String oversized = between;
		assertThrows(MalformedQueryException.class, () -> parser.parseQuery("RETURN " + oversized + " AS value", null));
		assertNotNull(parser.parseQuery("RETURN " + nullPredicate + " AS value", null));
	}

	@Test
	void chargesCopiesCreatedByNestedNullIfAgainstTheExpressionBudget() {
		String expression = "1";
		for (int i = 0; i < 9; i++) {
			expression = "NULLIF(" + expression + ", NULL)";
		}
		String oversized = expression;
		assertThrows(MalformedQueryException.class, () -> parser.parseQuery("RETURN " + oversized + " AS value", null));
	}

	@Test
	void boundsNumericLiteralsAndRejectsOverflow() {
		assertThrows(MalformedQueryException.class, () -> parser.parseQuery("RETURN 1e9999 AS value", null));
		String expression = "9".repeat(4097);
		assertThrows(MalformedQueryException.class,
				() -> parser.parseQuery("RETURN " + expression + " AS value", null));
	}

	@Test
	void oneParserCanServeConcurrentQueries() throws Exception {
		try (var executor = Executors.newFixedThreadPool(4)) {
			List<Callable<ParsedQuery>> tasks = new ArrayList<>();
			for (int i = 0; i < 64; i++) {
				String name = "column" + i;
				tasks.add(() -> {
					ParsedQuery parsed = parser.parseQuery("RETURN $parameter AS " + name, null);
					assertEquals(Set.of(name), parsed.getTupleExpr().getBindingNames());
					return parsed;
				});
			}
			for (var future : executor.invokeAll(tasks)) {
				assertNotNull(future.get());
			}
		}
	}
}
